<template>
  <sf-sheet class="coach-credits-purchase" :open="true" contained :resizable="false" :title="title" :busy="busy" @input="$emit('close')">
    <span class="coach-credits-purchase__icon"><sf-icon :name="gate.stage==='success'?'check':'coach'" :size="28"/></span>
    <template v-if="['offer','processing'].includes(gate.stage)">
      <h3 v-copy-block="'actions.credits'" class="operations-copy-title">{{ $copy('actions.credits.title') }}</h3><p>{{ $copy('actions.credits.description') }}</p>
      <div v-if="selected" class="coach-credits-purchase__pack"><strong>{{ selected.product.credits.amount }}<small>AI Coach Credits</small></strong><span>{{ money(selected) }}<small>One-time purchase</small></span></div>
      <div v-if="offers.length>1" class="coach-credits-purchase__options" role="radiogroup" aria-label="AI Coach credit packs"><button v-for="offer in offers" :key="offer.offerId" type="button" role="radio" :aria-checked="offer.offerId===selected.offerId?'true':'false'" :disabled="busy" @click="$emit('select',offer)">{{ offer.product.credits.amount }} credits · {{ money(offer) }}</button></div>
      <p v-if="selected&&gate.context.creditCost" v-copy-block="{id:'actions.credits',fields:['actions.credits.usage']}" class="coach-credits-purchase__usage">{{ $copy('actions.credits.usage',{cost:gate.context.creditCost}) }}</p>
      <p v-if="selected" v-copy-block="{id:'actions.credits',fields:['actions.credits.terms']}" class="coach-credits-purchase__terms"><sf-icon name="check" :size="15"/>{{ $copy('actions.credits.terms') }}</p><p v-else role="status">Credit packs aren’t available right now.</p>
    </template>
    <template v-else><h3>{{ gate.stage==='success'?(selected?selected.product.credits.amount+' credits added':'Your credits are ready'):gate.stage==='pending'?'Confirming your purchase':gate.stage==='cancelled'?'Purchase canceled':'Payment didn’t go through' }}</h3><p>{{ gate.stage==='success'?(gate.context.draft?'Your message is ready when you are.':'Use them whenever you’re ready.'):gate.stage==='pending'?'Please wait for confirmation before buying again.':'Your message is still here. No credits have been added.' }}</p></template>
    <div v-if="gate.context.draft" class="coach-credits-purchase__message"><small>YOUR UNSENT MESSAGE</small><p>{{ gate.context.draft }}</p></div>
    <p v-if="gate.feedback" role="status">{{ gate.feedback }}</p>
    <template #footer>
      <sf-button v-if="gate.stage==='success'" @click="$emit('resume')">{{ gate.context.messageId?$copy('actions.chat.resendMessage'):gate.context.continueLabel }}</sf-button>
      <sf-button v-else-if="['failure','cancelled'].includes(gate.stage)" @click="$emit('retry')">Back to credit packs</sf-button>
      <sf-button v-else-if="gate.stage==='pending'" @click="$emit('check')">Check purchase status</sf-button>
      <sf-button v-copy-block="'actions.credits'" v-else :disabled="!selected||busy" @click="$emit('purchase',selected)">{{ busy?'Confirming purchase…':selected?$copy('actions.credits.buy',{price:money(selected)}):'Credit packs unavailable' }}</sf-button>
      <button class="coach-credits-purchase__back" type="button" :disabled="busy" @click="$emit('close')">{{ gate.stage==='pending'?'Return while we confirm':'Back to conversation' }}</button>
    </template>
  </sf-sheet>
</template>
<script>
import {SfSheet,SfButton,SfIcon} from '@/design-system'
export default {components:{SfSheet,SfButton,SfIcon},props:{gate:Object,offers:{type:Array,default:()=>[]}},computed:{selected(){if(this.gate.stage==='success'&&this.gate.offer)return this.gate.offer;return this.offers.find(o=>o.offerId===this.gate.offer?.offerId)||this.offers[0]},busy(){return this.gate.stage==='processing'},title(){return this.gate.stage==='success'?'Credits added':'Add AI Coach Credits'}},methods:{money(offer){return new Intl.NumberFormat('en-US',{style:'currency',currency:offer.sku.currency}).format(offer.sku.priceCents/100)}}}
</script>
<style scoped>
.operations-copy-title{white-space:pre-line}
.coach-credits-purchase >>> .sf-modal{background:var(--sf-page);color:var(--sf-text);border-radius:24px 24px 0 0;max-height:calc(100% - 44px)}.coach-credits-purchase >>> .sf-modal__header h2{font-size:17px;line-height:24px}.coach-credits-purchase >>> .sf-modal__footer{border:0;background:var(--sf-page)}.coach-credits-purchase__icon{display:grid;place-items:center;width:50px;height:50px;background:var(--sf-content-surface);color:var(--sf-action);border-radius:17px;margin:8px 0 18px}.coach-credits-purchase h3{font-size:27px;line-height:32px;letter-spacing:-.6px;margin:0 0 12px}.coach-credits-purchase p{font-size:14px;line-height:22px;color:var(--sf-text-secondary);margin:0 0 18px}.coach-credits-purchase__pack{display:flex;align-items:center;justify-content:space-between;padding:18px 16px;border-radius:var(--sf-radius-card);border:1px solid var(--sf-content-edge);background:var(--sf-content-surface);margin:22px 0 14px}.coach-credits-purchase__pack strong{font-size:32px;line-height:38px;letter-spacing:-.8px}.coach-credits-purchase__pack span{font-size:23px;font-weight:600;line-height:32px;text-align:right}.coach-credits-purchase__pack small{display:block;font-size:12px;line-height:20px;font-weight:400;letter-spacing:0;color:var(--sf-text-secondary)}.coach-credits-purchase__terms{display:flex;gap:6px;align-items:center;font-size:12px!important;line-height:19px!important}.coach-credits-purchase__terms .sf-icon{color:#4f8568;flex-shrink:0}.coach-credits-purchase__message{padding:13px 15px;border-radius:var(--sf-radius-row);background:var(--sf-content-surface);margin-top:20px}.coach-credits-purchase__message small{font-size:10px;letter-spacing:.5px;color:var(--sf-text-secondary)}.coach-credits-purchase__message p{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;white-space:pre-wrap;margin:5px 0 0;color:var(--sf-text)}.coach-credits-purchase__back{width:100%;min-height:44px;border:0;background:none;font:13px/20px var(--sf-font-family);color:var(--sf-text-secondary);cursor:pointer}.coach-credits-purchase__options{display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap}.coach-credits-purchase__options button{min-height:44px;border:1px solid #dde2eb;border-radius:12px;padding:8px;font:12px/18px var(--sf-font-family);background:white;color:var(--sf-text-secondary);cursor:pointer}.coach-credits-purchase__options button[aria-checked=true]{color:var(--sf-action);border-color:var(--sf-action)}
</style>
